const CAT=Object.assign(Object.create(null),{RATE:'금리',CREDIT:'크레딧',FX:'FX',HEDGE:'헤지',MACRO:'매크로',KTB_DEMAND:'국채 수요',KTB_SUPPLY:'국채 공급',CREDIT_SUPPLY:'크레딧 공급',BOND_INDEX:'채권 지수',FUTURES:'선물'});
