const val=(key,idx=current)=>idx>=0&&idx<rows.length?rows[idx][Number(key)-1]:null;
const num=(v,n=2)=>v===null||!Number.isFinite(v)?'—':v.toLocaleString('ko-KR',{minimumFractionDigits:n,maximumFractionDigits:n});
const sign=(v,n=2)=>{if(v===null||!Number.isFinite(v))return '—';v=Number(v.toFixed(n));return(v>0?'+':v<0?'−':'')+num(Math.abs(v),n);};
const cls=v=>v===null||Math.abs(v)<1e-9?'flat':v>0?'up':'down';
function delta(key,a=current,b=current-lag){const m=byKey[key],x=val(key,a),y=val(key,b);if(x===null||y===null)return null;return m.mode==='bp'?(x-y)*100:m.mode==='pct'?(y===0?null:(x/y-1)*100):x-y;}
const changeUnit=m=>m.mode==='bp'?'bp':m.mode==='pct'?'%':m.unit;
function diff(a,b,idx=current){const x=val(a,idx),y=val(b,idx);return x===null||y===null?null:(x-y)*100;}
function spreadChange(a,b){const x=diff(a,b),y=diff(a,b,current-lag);return x===null||y===null?null:x-y;}
function findBefore(date){let l=0,r=dates.length-1,ans=-1;while(l<=r){let mid=(l+r)>>1;if(dates[mid]<=date){ans=mid;l=mid+1}else r=mid-1}return ans;}
function rangeStart(period=range){if(period==='CUSTOM'){const bounds=DateRanges.resolve(dates,customDates.from,dates[current]);if(bounds.error)throw new Error(bounds.error);return bounds.begin;}return DateRanges.preset(dates,period,current).begin;}
function spark(values,color='#2866d9'){const finite=values.filter(x=>x!==null);if(!finite.length)return '';let lo=Math.min(...finite),hi=Math.max(...finite),span=hi-lo||1;let path='',open=false;values.forEach((v,i)=>{if(v===null){open=false;return}let x=1+i*158/Math.max(1,values.length-1),y=28-(v-lo)/span*24;path+=(open?'L':'M')+x.toFixed(1)+','+y.toFixed(1);open=true});return `<svg viewBox="0 0 160 32" preserveAspectRatio="none" aria-hidden="true"><path d="${path}" fill="none" stroke="${color}" stroke-width="1.8" vector-effect="non-scaling-stroke"/></svg>`;}
