function renderRates(){const countries=[['한국',11,6],['미국',36,32],['일본',52,47],['독일',72,68],['호주',63,59],['영국',81,77]];$('globalRates').innerHTML=countries.map(([label,ten,two])=>{let d=delta(ten);return `<tr><td class="rate-label">${label}</td><td>${num(val(ten),3)}</td><td class="${cls(d)}">${sign(d,1)}<span class="bpbar"><i style="width:${Math.min(54,Math.abs(d??0)/25*54)}px;background:${d>0?'#bd354b':'#176fb5'}"></i></span></td><td>${num(diff(ten,two),1)}</td></tr>`}).join('');}
function renderCurve(){const pairs=C[$('curveCountry').value],past=current-lag;$('curveLegend').innerHTML=`<span><i style="background:#2866d9"></i>${dates[current]}</span><span><i style="background:#a7b7cd"></i>${dates[past]||'비교일 없음'}</span>`;drawChart('curve',[{values:pairs.map(p=>val(p[0])),color:'#2866d9',name:dates[current]},{values:pairs.map(p=>val(p[0],past)),color:'#a7b7cd',name:dates[past]||'비교일 없음',dash:true}],pairs.map(p=>p[1]),'%',{allLabels:true,dots:true,title:'국채 수익률곡선'});}
