function renderFx(){const list=[[20,'USD/KRW'],[21,'DXY'],[22,'USD/JPY'],[24,'USD/CNY'],[25,'유로/달러*'],[28,'AUD/USD']];$('fxList').innerHTML=list.map(([k,label])=>`<div class="fxitem"><span style="font-size:14px">${label}</span><b>${num(val(k),[24,25,28].includes(k)?4:2)}</b><span class="change ${cls(delta(k))}">${sign(delta(k))}%</span><small>${k===25?'*원본 USDEUR':escape(byKey[k].unit)}</small></div>`).join('');$('hedgeList').innerHTML=[[193,'3개월'],[194,'6개월'],[195,'12개월']].map(([k,label])=>`<div class="flowrow"><span>${label}</span><span><b>${num(val(k))}</b> <span class="${cls(delta(k))}" style="margin-left:18px">${sign(delta(k))}</span></span></div>`).join('');}
function renderFlows(){$('flowList').innerHTML=[[210,'외국인'],[211,'기금'],[212,'보험'],[216,'은행']].map(([k,label])=>`<div class="flowrow"><span>${label}</span><b class="${cls(val(k))}">${sign(val(k)===null?null:val(k)/100000,1)}</b></div>`).join('');$('futuresList').innerHTML=[[237,'3년 선물 내재수익률'],[240,'3년 선물 저평가'],[250,'10년 선물 내재수익률'],[253,'10년 선물 저평가']].map(([k,label])=>`<div class="flowrow"><span>${label}</span><span><b>${num(val(k))} ${byKey[k].unit==='원자료'?'':escape(byKey[k].unit)}</b> <span class="${cls(delta(k))}" style="margin-left:12px">${sign(delta(k))} ${changeUnit(byKey[k])==='원자료'?'':escape(changeUnit(byKey[k]))}</span></span></div>`).join('');}
function matches(m){if(category!=='ALL'&&m.category!==category&&!(category==='SUPPLY'&&['KTB_DEMAND','KTB_SUPPLY','CREDIT_SUPPLY'].includes(m.category)))return false;const q=$('search').value.trim().toLowerCase();return !q||[m.label,m.id,m.ticker,m.field,m.column,m.category].join(' ').toLowerCase().includes(q);}
