function showInfo(key){if(!dates.length)return;const m=byKey[key],first=rows.findIndex(r=>r[m.index-1]!==null);let last=rows.length-1;while(last>=0&&rows[last][m.index-1]===null)last--;$('infoContent').innerHTML=`<h2>${escape(m.label)}</h2><p><b>원본 위치</b><br>DailyRate!${m.column}${D.sourceRows?.[0]||10}:${m.column}${D.sourceRows?.at(-1)||dates.length+9}</p><p><b>원본 DATES</b> ${escape(m.id)}<br><b>Notation</b> ${escape(m.notation)}<br><b>Ticker</b> ${escape(m.ticker)}<br><b>필드</b> ${escape(m.field)}<br><b>분류</b> ${escape(m.category)}</p><p><b>표시 단위</b> ${escape(m.unit)} · 변동 ${changeUnit(m)}<br><b>유효 범위</b> ${first<0?'없음':dates[first]+' ~ '+dates[last]}<br><b>유효 관측</b> ${m.count.toLocaleString()}개 · 0값 ${m.zero_count.toLocaleString()}개</p><p>${escape(m.note||'원본 저장값을 그대로 사용합니다. 0값은 보존하고 결측값은 채우지 않습니다.')}</p>`;$('infoDialog').showModal();}
function render(){if(!dates.length){renderEmpty();return;}setAnalysisEnabled(true);start=rangeStart();renderSource();$('asof').value=dates[current];$('snapshotNote').innerHTML=`조회 <b>${dates[current]}</b> · 비교 <b>${dates[current-lag]||'없음'}</b> · 파일 최신 관측 <b>${dates.at(-1)}</b>`;$('comparisonTag').textContent=lag===1?'직전 관측일 대비':`${lag}관측일 전 대비`;renderKpis();renderTrend();renderRates();renderCurve();renderCredit();renderFx();renderFlows();renderTable();const count=rows[current].filter(v=>v!==null).length,zeros=rows[current].filter(v=>v===0).length;$('qualityNote').innerHTML=`<b>조회일 품질</b> ${count}/${M.length}개 값 존재 · ${M.length-count}개 결측 · ${zeros}개 0값. 원본 수치의 시장 정확성은 외부 시세로 검증하지 않았습니다.`;renderSpread();renderQuant();}
