function spreadCurve(country){return C[country].map(([key,label])=>({key:String(key),label,years:SpreadMath.maturity(label)}));}
function spreadName(m){if(m.category!=='CREDIT')return m.label;return m.id.replace(/^PUBLIC_/,'공사채 ').replace(/^KDB_/,'특수채 ').replace(/^BANK_/,'은행채 ').replace(/^CARD_/,'카드채 ').replace(/^CAPITAL_/,'캐피탈채 ').replace(/^CORP_/,'회사채 ').replace(/_PLUS/g,'+').replace(/_MINUS/g,'−').replace(/_ZERO/g,'0').replace(/_/g,' ');}
