 const detail=$('spreadDetailMode').value;if(detail==='z'){$('spreadDetailTitle').textContent='이동 Z-score';$('spreadDetailCaption').textContent=`스프레드 수준 · ${window}행 창`;$('spreadDetailFoot').textContent='현재 관측 포함 · ±2 참고선 · 상수·결측 창은 계산하지 않음';if(roll.z.some(SpreadMath.finite))drawChart('spreadDetail',[{values:roll.z,color:'#7658ba',name:'Z-score'},{values:labels.map(()=>2),color:'#c9a163',name:'+2',dash:true},{values:labels.map(()=>-2),color:'#c9a163',name:'−2',dash:true}],labels,'Z',{title:'스프레드 이동 Z-score'});else {clearChartView('spreadDetail');$('spreadDetail').innerHTML='<div class="empty">Z-score를 계산할 관측이 부족하거나<br>이동창에 결측·상수값이 있습니다.</div>';}}else if(detail==='vol'){$('spreadDetailTitle').textContent='스프레드 변동성';$('spreadDetailCaption').textContent=`인접 관측행의 bp 차분 · ${window}행 창`;$('spreadDetailFoot').textContent='표본 표준편차 · 비연율 · 결측 구간 차분 없음';drawChart('spreadDetail',[{values:roll.vol,color:'#208b87',name:'bp 차분 표준편차'}],labels,'bp',{title:'스프레드 bp 변동 표준편차'});}else{$('spreadDetailTitle').textContent=s.kind==='oas'?'원본 OAS':'구성 금리';$('spreadDetailCaption').textContent=s.kind==='oas'?'별도 차감 금리 없음':'A와 B의 수준을 같은 축에서 비교';$('spreadDetailFoot').textContent=s.leftLabel+(s.kind==='oas'?' · 원본 bp 해석':' / '+s.rightLabel);const lines=[{values:s.left.slice(begin,current+1),color:'#2866d9',name:s.leftLabel}];if(s.kind!=='oas')lines.push({values:s.right.slice(begin,current+1),color:'#7658ba',name:s.rightLabel});drawChart('spreadDetail',lines,labels,s.kind==='oas'?'bp':'%',{title:'스프레드 구성값'});}
