function saveBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csvCell(v){let s=String(v??'');if(typeof v==='string'&&/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function refreshNotes(){if(!rows.length){for(const m of M)m.note='';return;}const duplicate=rows.length>0&&rows.every(r=>r[187]===r[191]);for(const m of M){if([188,192].includes(m.index))m.note=duplicate?`미국 BEI 5Y와 10Y가 ${rows.length.toLocaleString()}개 날짜행에서 결측을 포함해 모두 동일합니다. 원본 확인이 필요합니다.`:'';if([14,28].includes(m.index)){let n=0;while(n<rows.length&&rows[n][m.index-1]===0)n++;m.note=n?`${m.id}의 첫 ${n.toLocaleString()}개 관측값이 0입니다 (${dates[0]} ~ ${dates[n-1]}). 결측 대체값 가능성을 확인하세요.`:'';}}}
function renderSource(){
 $('sourceBadge').textContent=D.source.name;$('obsCount').textContent=dates.length.toLocaleString();$('indicatorCount').textContent=M.length.toLocaleString();$('categoryCount').textContent=new Set(M.map(m=>m.category)).size;
 $('sourceDetail').textContent='출처 '+D.source.name+' / DailyRate · 이 브라우저에서 읽은 파일';
 $('sourceRange').textContent=`포함 범위 ${dates[0]} ~ ${dates.at(-1)} · ${dates.length.toLocaleString()}관측일. 파일 설정 종료일 ${D.source.configuredEnd||'미지정'}. 읽은 날짜 ${D.source.retrieved||'미기록'}. 수식은 Excel 저장 계산값을 읽으며 재계산하지 않습니다.`;
 const issues=[188,14,28].map(k=>byKey[k]?.note).filter(Boolean);$('sourceAnomalies').textContent='원본 확인 '+(issues.length?issues.join(' '):'지정 BEI 중복 및 시작 구간 0값 검사에서 경고가 없습니다.');
 $('footerSource').textContent=`읽은 날짜 ${D.source.retrieved||'미기록'} · 브라우저 내부 처리`;renderImportDiagnostics(D.importDiagnostics);
}
function refreshOptions(){for(const m of M)if(!Object.hasOwn(CAT,m.category))CAT[m.category]=m.category;const options=Object.entries(CAT).map(([cat,label])=>`<optgroup label="${escape(label)}">${M.filter(m=>m.category===cat).map(m=>`<option value="${m.key}">${escape(m.label)} · ${m.column}</option>`).join('')}</optgroup>`).join('');const value=$('series').value;$('series').innerHTML=options;$('series').value=byKey[value]?value:'20';selected=$('series').value;refreshSpreadInputs();refreshQuantOptions();}
function setData(next){chartViews.clear();document.querySelectorAll('.chart-tools').forEach(el=>el.remove());D=next;dates=D.dates;rows=D.values;M=D.meta;byKey=Object.fromEntries(M.map(m=>[m.key,m]));current=dates.length-1;refreshNotes();refreshOptions();$('asof').min=dates[0]||'';$('asof').max=dates.at(-1)||'';$('asof').value=dates.at(-1)||'';$('dateMessage').classList.add('sr');reconcileDateRanges();render();}
$('uploadBtn').addEventListener('click',()=>$('excelFile').click());
$('excelFile').addEventListener('change',async()=>{const file=$('excelFile').files?.[0];if(!file)return;const status=$('uploadStatus');status.className='upload-status';const busy=v=>{for(const id of ['uploadBtn','saveHtmlBtn','resetDataBtn','clearDataBtn'])$(id).disabled=v;};busy(true);try{if(!/\.xlsx$/i.test(file.name))throw new Error('.xlsx 형식만 지원합니다. .xls 파일은 Excel에서 .xlsx로 저장해주세요.');if(file.size>32*1024*1024)throw new Error('32MB 이하의 .xlsx 파일을 선택하세요.');const parsed=await ExcelImport.parse(await file.arrayBuffer(),OPENED_DATA.meta.filter(m=>m.index<=260),msg=>{status.textContent=msg;});const now=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'});const next={meta:parsed.meta,dates:parsed.dates,values:parsed.values,sourceRows:parsed.sourceRows,source:{name:file.name,sheet:'DailyRate',folder:'로컬 업로드',retrieved:now,configuredEnd:parsed.configuredEnd,url:null},importWarnings:parsed.warnings,importDiagnostics:parsed.diagnostics};setData(next);dataWasUploaded=true;const w=parsed.warnings,notes=[];if(w.cachedMissing)notes.push(`수식 계산값 없음 ${w.cachedMissing}셀`);if(w.errors)notes.push(`오류값 ${w.errors}셀`);if(w.textValues)notes.push(`비숫자/비정상 숫자 ${w.textValues}셀`);if(w.numericStrings)notes.push(`숫자 문자열 변환 ${w.numericStrings}셀`);if(parsed.diagnostics?.counts.missingValues)notes.push(`결측 ${parsed.diagnostics.counts.missingValues.toLocaleString()}셀`);if(w.extraCols)notes.push(`추가 ${w.extraCols}개 지표 인식`);status.className='upload-status success';status.textContent=`${file.name} · ${M.length.toLocaleString()}개 지표 · ${dates.length.toLocaleString()}관측일 · ${dates.at(-1)}까지 갱신 완료. ${notes.length?notes.join(' · ')+'. ':''}데이터 포함 HTML 저장 파일에는 업로드한 금융시계열이 들어갑니다. 공유 전에 공개 범위를 확인하세요.`;}catch(e){status.className='upload-status error';status.textContent='업로드 실패: '+e.message+' 기존 데이터는 유지됩니다.';renderImportDiagnostics(e.diagnostics,'최근 실패한 업로드 · 기존 분석 데이터 유지');}finally{busy(false);$('saveHtmlBtn').disabled=!dates.length;$('clearDataBtn').disabled=!dates.length;$('resetDataBtn').disabled=!dataWasUploaded||!OPENED_DATA.dates.length;$('excelFile').value='';}});
$('resetDataBtn').addEventListener('click',()=>{setData(OPENED_DATA);dataWasUploaded=false;$('resetDataBtn').disabled=true;$('uploadStatus').className='upload-status';$('uploadStatus').textContent='HTML을 처음 열었을 때의 데이터로 복원했습니다.';});
$('saveHtmlBtn').addEventListener('click',()=>{if(!dates.length)return;try{const clone=document.documentElement.cloneNode(true);clone.querySelector('#dataset').textContent=JSON.stringify({...D,spreadSettings:exportSpreadSettings(),analysisSettings:exportAnalysisSettings()}).replace(/<\//g,'<\\/');clone.querySelector('#infoDialog').removeAttribute('open');clone.querySelector('#uploadStatus').textContent='저장된 데이터로 열었습니다. 새 엑셀을 업로드하여 갱신할 수 있습니다.';clone.querySelector('#uploadStatus').className='upload-status';clone.querySelector('#resetDataBtn').setAttribute('disabled','');for(const id of ['uploadBtn','saveHtmlBtn'])clone.querySelector('#'+id).removeAttribute('disabled');for(const id of ['excelFile','search'])clone.querySelector('#'+id).removeAttribute('value');clone.querySelector('#infoContent').innerHTML='';saveBlob(new Blob(['<!DOCTYPE html>\n'+clone.outerHTML],{type:'text/html;charset=utf-8'}),`FICC_Monitor_${dates.at(-1)}.html`);$('uploadStatus').textContent='전체 업로드 데이터를 포함한 HTML 다운로드를 시작했습니다. 민감·비공개 자료가 있을 수 있으므로 파일 공유 전에 확인하세요.';}catch(e){$('uploadStatus').className='upload-status error';$('uploadStatus').textContent='HTML 저장 실패: '+e.message;}});
function initQuant(){refreshQuantOptions();$('quantX').value='36';$('quantY').value='11';for(const id of ['quantX','quantY','quantTransform','quantWindow','quantAnnual'])$(id).addEventListener('change',renderQuant);$('quantRange').addEventListener('change',()=>areaPeriodChanged('quant'));}
function quantUnit(m,mode){return mode==='level'?m.unit:mode==='auto'?changeUnit(m):['pct','log'].includes(mode)?'%':m.unit;}
function scatterPlot(pairs,model,ux,uy){const el=$('quantScatter');if(!pairs.length){el.innerHTML='<div class="empty">동일 날짜의 유효 X·Y 관측쌍이 없습니다.</div>';return;}const W=700,H=255,L=67,R=20,T=22,B=46,pw=W-L-R,ph=H-T-B;let xmin=Math.min(...pairs.map(p=>p.x)),xmax=Math.max(...pairs.map(p=>p.x)),ymin=Math.min(...pairs.map(p=>p.y)),ymax=Math.max(...pairs.map(p=>p.y));let xp=(xmax-xmin)*.1||Math.max(.02,Math.abs(xmax)*.01),yp=(ymax-ymin)*.12||Math.max(.02,Math.abs(ymax)*.01);xmin-=xp;xmax+=xp;ymin-=yp;ymax+=yp;const sx=v=>L+(v-xmin)/(xmax-xmin)*pw,sy=v=>T+(ymax-v)/(ymax-ymin)*ph;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="X Y 산점도와 회귀선"><defs><clipPath id="scatterClip"><rect x="${L}" y="${T}" width="${pw}" height="${ph}"/></clipPath></defs><text x="${L}" y="13">Y · ${escape(uy)}</text><text x="${W-R}" y="${H-1}" text-anchor="end">X · ${escape(ux)}</text>`;for(let i=0;i<=4;i++){let vx=xmin+(xmax-xmin)*i/4,vy=ymin+(ymax-ymin)*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${sy(vy)}" y2="${sy(vy)}" stroke="#e6edf4"/><text x="${L-9}" y="${sy(vy)+4}" text-anchor="end">${num(vy,Math.abs(vy)>10000?0:2)}</text><text x="${sx(vx)}" y="${H-23}" text-anchor="middle">${num(vx,Math.abs(vx)>10000?0:2)}</text>`;}const stride=Math.max(1,Math.ceil(pairs.length/3000));svg+='<g clip-path="url(#scatterClip)">';for(let i=0;i<pairs.length;i+=stride){const p=pairs[i];svg+=`<circle cx="${sx(p.x).toFixed(2)}" cy="${sy(p.y).toFixed(2)}" r="2.8" fill="#7658ba" fill-opacity=".5"><title>${dates[p.i]} | X ${num(p.x,4)} ${escape(ux)} | Y ${num(p.y,4)} ${escape(uy)}</title></circle>`;}if(model.valid){const pred=x=>model.my+model.beta*(x-model.mx);svg+=`<line x1="${sx(xmin)}" y1="${sy(pred(xmin))}" x2="${sx(xmax)}" y2="${sy(pred(xmax))}" stroke="#ed9636" stroke-width="2.3"/>`;}svg+='</g></svg>';$('quantScatter').innerHTML=svg;}
function renderQuant(){if(!dates.length||!$('quantX').value)return;renderPeriodStatus();const xkey=$('quantX').value,ykey=$('quantY').value,mode=$('quantTransform').value,window=+$('quantWindow').value,begin=rangeStart($('quantRange').value),xi=quantInput(xkey),yi=quantInput(ykey),mx=xi.meta,my=yi.meta,x=Quant.transform(xi.values,mode,mx.mode),y=Quant.transform(yi.values,mode,my.mode),a=Quant.analyze(x,y,begin,current,window),model=a.model,ux=quantUnit(mx,mode),uy=quantUnit(my,mode);$('quantAnnual').disabled=mode==='level';if(mode==='level')$('quantAnnual').checked=false;const annual=$('quantAnnual').checked,mult=annual?Math.sqrt(252):1,vol=a.vol.map(v=>v===null?null:v*mult),n=a.pairs.length,lastZ=a.z.at(-1),lastVol=vol.at(-1),firstPair=a.pairs[0],lastPair=a.pairs.at(-1);quantCache={...a,x,y,rawX:xi.values,rawY:yi.values,xLabel:mx.label,yLabel:my.label,xDefinition:mx.definition||'원본 시계열',yDefinition:my.definition||'원본 시계열',xZero:mx.derived?(mx.excludeZero?'yes':'no'):'해당 없음',yZero:my.derived?(my.excludeZero?'yes':'no'):'해당 없음',begin,end:current,xkey,ykey,mode,window,ux,uy,vol,annual};$('quantCaption').textContent=`${dates[begin]} ~ ${dates[current]} · X: ${mx.label} [${ux}] · Y: ${my.label} [${uy}] · 동일 날짜 유효쌍 ${n.toLocaleString()}/${current-begin+1} · 이동창·차분은 시작일 이전 이력도 사용`;$('quantMetrics').innerHTML=[['상관계수 r',num(model.r??null,3),'동일 날짜 관측쌍'],['회귀계수 β',num(model.beta??null,4),`${uy} / ${ux}`],['설명력 R²',model.r2===null||model.r2===undefined?'—':num(model.r2*100,1)+'%','절편 포함 회귀'],[`Y ${window}행 표준편차`,num(lastVol,3),uy+(annual?' · √252 적용':' · 비연율')],[`Y ${window}행 Z-score`,num(lastZ,2),'현재 관측 포함 창']].map(([label,value,detail])=>`<div class="quant-metric"><span>${escape(label)}</span><b>${value}</b><small>${escape(detail)}</small></div>`).join('');const warnings=[];for(const [axis,meta] of [['X',mx],['Y',my]]){if(!meta.derived)continue;if(meta.sourceError)warnings.push(axis+': '+meta.sourceError);for(const message of meta.sourceWarnings||[])warnings.push(axis+': '+message);const zeros=rows.slice(Math.max(0,begin-window),current+1).filter(r=>(meta.sourceLegs||[]).some(l=>r[Number(l.key)-1]===0)).length;if(zeros)warnings.push(`${axis}: 분석·이동창 준비 구간에 구성 원값 0인 날짜 ${zeros.toLocaleString()}개 (${meta.excludeZero?'제외':'포함; 원본 대체값 가능성 확인'}).`);}if(model.reason)warnings.push(model.reason);if(xkey===ykey)warnings.push('X와 Y가 같은 지표입니다. 두 지표를 다르게 선택하면 관계를 비교할 수 있습니다.');if(mode==='level')warnings.push('수준값 분석: 공통 추세로 상관이 높아질 수 있습니다.');if(a.corr.at(-1)===null)warnings.push(`조회일 기준 ${window}개 연속 관측행이 부족하거나 결측·상수 창으로 이동 상관이 계산되지 않습니다.`);if(lastZ===null)warnings.push('조회일 Z-score는 관측 부족·결측·상수 창으로 계산되지 않습니다.');if(rows.slice(begin,current+1).some(r=>r[mx.index-1]===0||r[my.index-1]===0))warnings.push('분석 기간의 원본에 0값이 있습니다. 원본 정보에서 확인하세요.');$('quantWarning').textContent=warnings.join(' ');$('quantPairCount').textContent=`n = ${n.toLocaleString()}`;scatterPlot(a.pairs,model,ux,uy);$('quantEquation').innerHTML=model.valid?`<span>α <b>${num(model.alpha,4)}</b></span><span>β <b>${num(model.beta,4)}</b></span><span>잔차 표준편차 <b>${num(model.residualSd,4)} ${escape(uy)}</b></span><span>${firstPair?dates[firstPair.i]+' ~ '+dates[lastPair.i]:''}${n>3000?' · 점은 최대 3,000개 표시, 회귀는 전체 사용':''}</span>`:'<span>관측쌍 3개 이상과 X의 변동이 필요합니다.</span>';$('quantCorrSub').textContent=`${window}개 연속 관측행 · 창의 모든 X·Y 필요`;const labels=dates.slice(begin,current+1);drawChart('quantCorr',[{values:a.corr,color:'#7658ba',name:'이동 상관'}],labels,'r',{title:'이동 Pearson 상관계수',fixedMin:-1,fixedMax:1});drawChart('quantVol',[{values:vol,color:'#208b87',name:'Y 표준편차'}],labels,uy+(annual?' (√252)':''),{title:'Y 이동 표준편차'});$('quantVolNote').textContent=`표본 표준편차 · ${window}행 창 · ${annual?'연 252관측일 가정 배율 적용':'연율화하지 않은 관측 간 변동'}`;const validZ=a.z.some(v=>v!==null);if(validZ)drawChart('quantZ',[{values:a.z,color:'#2866d9',name:'Z-score'},{values:labels.map(()=>2),color:'#c9a163',name:'+2',dash:true},{values:labels.map(()=>-2),color:'#c9a163',name:'−2',dash:true}],labels,'Z',{title:'Y 이동 Z-score'});else {clearChartView('quantZ');$('quantZ').innerHTML='<div class="empty">표시할 Z-score가 없습니다.<br>이동창을 줄이거나 다른 지표·변환을 선택하세요.</div>';}$('quantCsvBtn').disabled=!n;$('quantExportNote').textContent='원값·변환값·적합값·잔차·이동통계를 함께 저장';renderQuantSummary(quantCache, mx, my);}
$('quantCsvBtn').addEventListener('click',()=>{const q=quantCache;if(!q)return;const header=['원본파일','날짜','X지표','Y지표','변환','이동창','X원값','Y원값','X변환값','Y변환값','X단위','Y단위','적합Y','잔차','이동상관','Y이동표준편차','연율화252','YZscore','X정의','Y정의','X스프레드원값0제외','Y스프레드원값0제외','분석기간시작','분석기간끝','회귀유효쌍n','절편alpha','기울기beta','상관r','결정계수r2','결측처리','표준편차정의'];const out=[header];for(let i=q.begin;i<=q.end;i++){const k=i-q.begin,x=q.x[i],y=q.y[i],pred=q.model.valid&&Quant.finite(x)?q.model.my+q.model.beta*(x-q.model.mx):null;out.push([D.source.name,dates[i],q.xLabel,q.yLabel,q.mode,q.window,q.rawX[i],q.rawY[i],x,y,q.ux,q.uy,pred,pred===null||y===null?null:y-pred,q.corr[k],q.vol[k],q.annual?'yes':'no',q.z[k],q.xDefinition,q.yDefinition,q.xZero,q.yZero,dates[q.begin],dates[q.end],q.pairs.length,q.model.alpha,q.model.beta,q.model.r,q.model.r2,'무대체·회귀는동일날짜유효쌍·이동창전체값필요','표본n-1·회귀잔차n-2']);}saveBlob(new Blob(['\ufeff'+out.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),`FICC_Quant_${dates[current]}.csv`);});
$('compare').value='1';$('chartMode').value='raw';$('curveCountry').value='KR';for(const b of $('ranges').children){b.classList.toggle('active',b.dataset.range===range);b.setAttribute('aria-pressed',b.dataset.range===range);}
