let customDates={from:dates.length?DateRanges.subtractCalendar(dates[current],'1Y'):'',to:dates[current]||''},periodNotice='';
const periodModes={trend:['1M','3M','1Y','3Y','ALL','CUSTOM'],spread:['3M','6M','1Y','3Y','ALL','CUSTOM'],quant:['3M','6M','1Y','3Y','ALL','CUSTOM']};
function areaMode(area){return area==='trend'?range:$(area==='spread'?'spreadRange':'quantRange').value;}
function setAreaMode(area,value){if(area==='trend')range=value;else $(area==='spread'?'spreadRange':'quantRange').value=value;}
function anyCustomPeriod(){return ['trend','spread','quant'].some(a=>areaMode(a)==='CUSTOM');}
function syncRangeButtons(){for(const b of $('ranges').children){b.classList.toggle('active',b.dataset.range===range);b.setAttribute('aria-pressed',b.dataset.range===range);}}
function syncCustomFields(){$('analysisFrom').value=customDates.from;$('analysisTo').value=customDates.to;syncRangeButtons();}
function renderPeriodStatus(){if(!dates.length)return;const modes=['trend','spread','quant'].map(a=>{const mode=areaMode(a),title={trend:'시장 추이·표',spread:'스프레드',quant:'계량분석'}[a];const first=mode==='CUSTOM'?DateRanges.lower(dates,customDates.from):DateRanges.preset(dates,mode,current).begin;return `${title}: ${mode==='CUSTOM'?'직접 설정':mode==='ALL'?'전체':mode} (${dates[first]} ~ ${dates[current]})`;});$('periodStatus').className='period-status'+(periodNotice?' period-notice':'');$('periodStatus').textContent=(periodNotice?periodNotice+' ':'')+modes.join(' · ');$('availableRange').textContent=`파일 관측 범위 ${dates[0]} ~ ${dates.at(-1)}`;}
function applyCustomDates(all=true,area=null){const from=all?$('analysisFrom').value:customDates.from,to=all?$('analysisTo').value:customDates.to,bounds=DateRanges.resolve(dates,from,to);if(bounds.error){$('periodError').textContent=bounds.error;return false;}customDates={from,to};current=bounds.end;if(all){for(const a of ['trend','spread','quant'])setAreaMode(a,'CUSTOM');}else setAreaMode(area,'CUSTOM');periodNotice=`요청 ${from} ~ ${to} → 실제 ${bounds.actualFrom} ~ ${bounds.actualTo} (${bounds.count.toLocaleString()}관측일).`;$('periodError').textContent='';$('dateMessage').classList.add('sr');syncCustomFields();render();return true;}
function areaPeriodChanged(area){if(areaMode(area)==='CUSTOM'){if(!applyCustomDates(false,area)){setAreaMode(area,'1Y');render();}return;}periodNotice='';$('periodError').textContent='';syncRangeButtons();render();}
function changeAsOf(requested){if(!DateRanges.validDate(requested)||requested<dates[0]||requested>dates.at(-1)){$('dateMessage').classList.remove('sr');$('dateMessage').textContent=`${dates[0]} ~ ${dates.at(-1)} 범위 안의 날짜를 선택하세요.`;$('asof').value=dates[current];return false;}let end=DateRanges.upper(dates,requested)-1;if(anyCustomPeriod()){const bounds=DateRanges.resolve(dates,customDates.from,requested);if(bounds.error){$('dateMessage').classList.remove('sr');$('dateMessage').textContent='조회 기준일 변경 불가: '+bounds.error;$('asof').value=dates[current];return false;}customDates.to=requested;end=bounds.end;periodNotice=`조회 기준일 변경에 따라 직접 설정 종료일을 ${requested}로 변경했습니다. 실제 종료 관측일 ${dates[end]}.`;syncCustomFields();}else periodNotice='';current=end;$('periodError').textContent='';render();const snapped=dates[end]!==requested;$('dateMessage').classList.toggle('sr',!snapped);$('dateMessage').textContent=snapped?`${requested}에 관측이 없어 ${dates[end]} 데이터를 표시합니다.`:'';return true;}
function defaultCustomDates(){customDates={from:dates.length?DateRanges.subtractCalendar(dates[current],'1Y'):'',to:dates[current]||''};}
function reconcileDateRanges(){if(!dates.length){defaultCustomDates();periodNotice='';syncCustomFields();return;}const active=anyCustomPeriod(),bounds=DateRanges.resolve(dates,customDates.from,customDates.to);if(active&&!bounds.error){current=bounds.end;periodNotice=`데이터 갱신 후 직접 기간 유지: 실제 ${bounds.actualFrom} ~ ${bounds.actualTo}.`;}else if(bounds.error){if(active)for(const a of ['trend','spread','quant'])setAreaMode(a,'1Y');current=dates.length-1;defaultCustomDates();periodNotice=active?'새 데이터와 직접 설정 기간이 겹치지 않아 최신 1년으로 초기화했습니다.':'직접 설정 날짜를 새 데이터의 최신 1년으로 초기화했습니다.';}else{current=dates.length-1;periodNotice='';}$('periodError').textContent='';syncCustomFields();}
function exportAnalysisSettings(){return {custom:{...customDates},asof:dates[current],trend:range,spread:$('spreadRange').value,quant:$('quantRange').value};}
function initDateRanges(){const p=D.analysisSettings;if(p&&dates.length){const bounds=DateRanges.resolve(dates,p.custom?.from,p.custom?.to);if(!bounds.error)customDates={from:p.custom.from,to:p.custom.to};for(const a of ['trend','spread','quant'])if(periodModes[a].includes(p[a]))setAreaMode(a,p[a]);const savedEnd=DateRanges.validDate(p.asof)?DateRanges.upper(dates,p.asof)-1:-1;if(savedEnd>=0&&savedEnd<dates.length)current=savedEnd;if(anyCustomPeriod()){const active=DateRanges.resolve(dates,customDates.from,dates[current]);if(active.error){for(const a of ['trend','spread','quant'])setAreaMode(a,'1Y');current=dates.length-1;defaultCustomDates();periodNotice='저장된 기간을 사용할 수 없어 최신 1년으로 초기화했습니다.';}else{current=active.end;customDates.to=p.custom?.to||dates[current];}}}else if(anyCustomPeriod()){for(const a of ['trend','spread','quant'])if(areaMode(a)==='CUSTOM')setAreaMode(a,'1Y');}syncCustomFields();$('analysisApply').addEventListener('click',()=>applyCustomDates(true));for(const id of ['analysisFrom','analysisTo'])$(id).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();applyCustomDates(true);}});}
initDateRanges();

function setAnalysisEnabled(enabled){
 for(const el of document.querySelectorAll('button,select,input')){if(['uploadBtn','excelFile','closeDialog'].includes(el.id))continue;el.disabled=!enabled;}
 $('resetDataBtn').disabled=!enabled||!dataWasUploaded||!OPENED_DATA.dates.length;
 $('clearDataBtn').disabled=!enabled;
}
function renderImportDiagnostics(diagnostics,title='현재 데이터 업로드 검증'){
 const el=$('importDiagnostics');if(!diagnostics){el.textContent='Excel을 업로드하면 날짜·숫자·수식 저장값·결측 검증 결과와 문제 셀 위치가 표시됩니다.';return;}
 const names={numericValues:'숫자값',missingValues:'결측값',zeroValues:'원값 0',numericStrings:'변환한 숫자 문자열',invalidNumbers:'비정상 숫자·문자',invalidDates:'잘못된 날짜',errorCells:'Excel 오류 셀',formulaMissingCache:'계산값 없는 수식',formulaErrorCaches:'오류 계산값 수식',formulasWithCachedValue:'저장 계산값 수식',blankRows:'빈 행',duplicateDates:'중복 날짜',invalidMetadata:'잘못된 열 정의',extraCols:'추가 인식 열'};
 el.innerHTML='<p><b>'+escape(title)+'</b> · 날짜체계 '+escape(diagnostics.dateSystem||'미확인')+' · 날짜 정렬 '+(diagnostics.sortedRows?'재정렬':'원본 순서 유지')+'</p><div class="diagnostic-counts">'+Object.entries(diagnostics.counts||{}).map(([key,value])=>'<span>'+escape(names[key]||key)+': <b>'+num(value,0)+'</b></span>').join('')+'</div>'+Object.entries(diagnostics.samples||{}).filter(([,samples])=>samples.length).map(([key,samples])=>'<p><b>'+escape(names[key]||key)+'</b> · 최대 '+escape(diagnostics.sampleLimit||8)+'개 예시: '+samples.map(sample=>escape(sample.cell)+' = '+escape(sample.value)).join(' / ')+'</p>').join('')+'<p class="sub">유효 날짜는 오름차순으로 정렬합니다. 중복 날짜·지표 정의·잘못된 날짜는 파일을 거부합니다. 결측·수식 계산값 없음·오류값은 숫자로 대체하지 않습니다. 진단의 예시 값도 저장 HTML에 포함될 수 있습니다.</p>';
}
